def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_json(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def display_path(path: Path) -> str:
    try:
        return path.relative_to(ROOT).as_posix()
    except ValueError:
        return path.as_posix()


def webp(path: Path, maximum: int, quality: int) -> str:
    with Image.open(path) as original:
        picture = ImageOps.exif_transpose(original).convert("RGB")
        picture.thumbnail((maximum, maximum), Image.Resampling.LANCZOS)
        memory = io.BytesIO()
        picture.save(memory, format="WEBP", quality=quality, method=5)
    return "data:image/webp;base64," + base64.b64encode(memory.getvalue()).decode("ascii")


assets: list[dict] = []


def add(identifier: str, path: Path, title: str, group: str, status: str,
        description: str, **extra: object) -> None:
    if not path.is_file():
        raise FileNotFoundError(f"Required report source missing: {path}")
    with Image.open(path) as image:
        dimensions = list(image.size)
    assets.append({
        "id": identifier, "title": title, "group": group, "status": status,
        "description": description, "path": display_path(path),
        "original_path": path.as_posix(), "original_url": path.as_uri(),
        "sha256": sha(path), "dimensions": dimensions,
        "thumb": webp(path, 720, 81), "full": webp(path, 1800, 87),
        **extra,
    })


