def document_link(path: str, title: str, detail: str) -> str:
    target = ROOT / path
    relative = Path("../../") / path
    exists = target.is_file()
    href = relative.as_posix()
    return (f'<li><a href="{html.escape(href)}">{html.escape(title)} <span aria-hidden="true">↗</span></a>'
            f'<p>{html.escape(detail)}</p><code>{html.escape(path)}</code>'
            f'<span class="file-state">{"vorhanden" if exists else "wird ergänzt"}</span></li>')


